// Mutable exercise map that includes custom exercises
export const EXERCISE_MAP = new Map(EXERCISES.map(e => [e.id, e]));

// Call this after loading custom exercises to merge them in
export function registerCustomExercises(custom: Exercise[]) {
  // Remove old custom entries
  for (const [id, ex] of EXERCISE_MAP) {
    if (ex.isCustom) EXERCISE_MAP.delete(id);
  }
  // Add new custom entries
  for (const ex of custom) {
    EXERCISE_MAP.set(ex.id, ex);
  }
}

export function getAllExercises(): Exercise[] {
  return Array.from(EXERCISE_MAP.values());
}

export function getExercisesByMuscle(muscle: MuscleGroup): Exercise[] {
  return getAllExercises().filter(e => e.primaryMuscle === muscle || e.secondaryMuscles.includes(muscle));
}

export function getExercisesByCategory(category: string): Exercise[] {
  return getAllExercises().filter(e => e.category === category);
}

export function searchExercises(query: string): Exercise[] {
  const lower = query.toLowerCase();
  return getAllExercises().filter(e =>
    e.name.toLowerCase().includes(lower) ||
    e.primaryMuscle.includes(lower) ||
    e.category.includes(lower)
  );
}

